    async def memory_search(
        self,
        *,
        query: str,
        diagnostics: typing.Optional[str] = None,
        project_id: typing.Optional[str] = OMIT,
        top_k: typing.Optional[int] = OMIT,
        as_of: typing.Optional[dt.datetime] = OMIT,
        as_of_system_time: typing.Optional[dt.datetime] = OMIT,
        as_of_valid_time: typing.Optional[dt.datetime] = OMIT,
        request_options: typing.Optional[RequestOptions] = None,
    ) -> MemorySearchResponse:
        """
        Parameters
        ----------
        query : str

        diagnostics : typing.Optional[str]
            Set to 1/true/yes to include per-stream diagnostics in the response (opt-in; also accepts X-Lore-Diagnostics request header)

        project_id : typing.Optional[str]

        top_k : typing.Optional[int]

        as_of : typing.Optional[dt.datetime]
            v1.4 bi-temporal: ISO 8601 datetime that sets BOTH asOfSystemTime and asOfValidTime to the same value. Use this for unified point-in-time queries ("what would Lore have answered at this moment?"). Mutually exclusive with asOfSystemTime and asOfValidTime.

        as_of_system_time : typing.Optional[dt.datetime]
            v1.4 bi-temporal: ISO 8601 datetime for the system-knowledge axis. Filters to facts that Lore had recorded by this timestamp (t_created <= asOfSystemTime) and had not yet expired (t_expired IS NULL OR t_expired > asOfSystemTime). Must not be in the future beyond 5 minutes. Mutually exclusive with asOf.

        as_of_valid_time : typing.Optional[dt.datetime]
            v1.4 bi-temporal: ISO 8601 datetime for the business-validity axis. Filters to facts whose validity window covers this timestamp (valid_from <= asOfValidTime AND (valid_until IS NULL OR valid_until > asOfValidTime)). Future values are allowed for forward-looking domain queries. Mutually exclusive with asOf.

        request_options : typing.Optional[RequestOptions]
            Request-specific configuration.

        Returns
        -------
        MemorySearchResponse
            Memory hits

        Examples
        --------
        import asyncio

        from lore_context import AsyncLoreContextClient

        client = AsyncLoreContextClient(
            lore_api_key="YOUR_LORE_API_KEY",
            lore_csrf="YOUR_LORE_CSRF",
            token="YOUR_TOKEN",
        )


        async def main() -> None:
            await client.memory_search(
                query="query",
            )


        asyncio.run(main())
        """
        response = await self._raw_client.memory_search(
            query=query,
            diagnostics=diagnostics,
            project_id=project_id,
            top_k=top_k,
            as_of=as_of,
            as_of_system_time=as_of_system_time,
            as_of_valid_time=as_of_valid_time,
            request_options=request_options,
        )
        return response.data

